```systemverilog
module sync_fifo4x8 (
  input logic clk, rst, wr_en, rd_en,
  input logic [7:0] din,
  output logic [7:0] dout,
  output logic rd_valid, full, empty,
  output logic [2:0] count
);
  logic [7:0] mem [0:3];
  logic [1:0] wptr, rptr;
  logic put, take;
  assign full = (count == 3'd4);
  assign empty = (count == 3'd0);
  // Acceptance uses the state BEFORE this edge: no full/empty bypass.
  assign put = wr_en && !full;
  assign take = rd_en && !empty;
  always_ff @(posedge clk) begin
    if (rst) begin
      wptr <= 2'd0;
      rptr <= 2'd0;
      count <= 3'd0;
      dout <= 8'd0;
      rd_valid <= 1'b0;
    end else begin
      rd_valid <= take;
      if (put) begin
        mem[wptr] <= din;
        wptr <= wptr + 2'd1;
      end
      if (take) begin
        dout <= mem[rptr];
        rptr <= rptr + 2'd1;
      end
      case ({put, take})
        2'b10: count <= count + 3'd1;
        2'b01: count <= count - 3'd1;
        default: ;
      endcase
    end
  end
endmodule
```

put/take分别由沿前count决定。接受读返回旧队首；输出rd_valid逐拍更新，dout无读时保持。

```systemverilog
module async_fifo_gray #(
  parameter integer WIDTH = 8,
  parameter integer ADDR_BITS = 2
) (
  input logic wclk, wrst_n, winc,
  input logic [WIDTH-1:0] wdata,
  output logic wfull,
  input logic rclk, rrst_n, rinc,
  output logic [WIDTH-1:0] rdata,
  output logic rvalid, rempty
);
  // Contract: WIDTH >= 1, ADDR_BITS >= 2; capacity is 2**ADDR_BITS.
  localparam integer DEPTH = 1 << ADDR_BITS;
  localparam logic [ADDR_BITS:0] FULL_MASK = {2'b11, {(ADDR_BITS-1){1'b0}}};
  logic [WIDTH-1:0] mem [0:DEPTH-1];
  logic [ADDR_BITS:0] wb, wg, rb, rg;
  logic [ADDR_BITS:0] wb_next, wg_next, rb_next, rg_next;
  (* ASYNC_REG = "TRUE" *) logic [ADDR_BITS:0] rg_w1, rg_w2;
  (* ASYNC_REG = "TRUE" *) logic [ADDR_BITS:0] wg_r1, wg_r2;
  logic put, take;

  assign put = winc && !wfull;
  assign take = rinc && !rempty;
  assign wb_next = wb + {{ADDR_BITS{1'b0}}, put};
  assign rb_next = rb + {{ADDR_BITS{1'b0}}, take};
  assign wg_next = (wb_next >> 1) ^ wb_next;
  assign rg_next = (rb_next >> 1) ^ rb_next;

  // Only registered Gray pointers cross domains, through two stages.
  always_ff @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      rg_w1 <= '0;
      rg_w2 <= '0;
    end else begin
      rg_w1 <= rg;
      rg_w2 <= rg_w1;
    end
  end
  always_ff @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      wg_r1 <= '0;
      wg_r2 <= '0;
    end else begin
      wg_r1 <= wg;
      wg_r2 <= wg_r1;
    end
  end

  always_ff @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wb <= '0;
      wg <= '0;
      wfull <= 1'b0;
    end else begin
      wb <= wb_next;
      wg <= wg_next;
      wfull <= (wg_next == (rg_w2 ^ FULL_MASK));
    end
  end
  // Memory is not reset. A read is permitted only after a published write.
  always_ff @(posedge wclk) begin
    if (wrst_n && put) mem[wb[ADDR_BITS-1:0]] <= wdata;
  end
  always_ff @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rb <= '0;
      rg <= '0;
      rempty <= 1'b1;
      rdata <= '0;
      rvalid <= 1'b0;
    end else begin
      rb <= rb_next;
      rg <= rg_next;
      rempty <= (rg_next == wg_r2);
      rvalid <= take;
      if (take) rdata <= mem[rb[ADDR_BITS-1:0]];
    end
  end
endmodule
```

wb/rb含绕回位，地址取低ADDR_BITS位；wg/rg为注册发布值。同步链只用于指针，数据通过存储阵列保持，直到读域获得所有权。rvalid在每个接受读的沿后为1，连续读可连续高，停读时清0；它不要求高电平之间必须插空拍。满/空采用本地next指针和旧的第二级同步指针，撤销会保守延后。参数范围已限定A>=2，未实现任意非2的幂深度或运行中单域清空协议。

```systemverilog
module gray_codec #(
  parameter integer WIDTH = 8
) (
  input logic [WIDTH-1:0] binary_in, gray_in,
  output logic [WIDTH-1:0] gray_out, binary_out
);
  // Contract: WIDTH >= 1. This is a combinational codec, not a CDC circuit.
  assign gray_out = binary_in ^ (binary_in >> 1);
  for (genvar bit_index = 0; bit_index < WIDTH; bit_index = bit_index + 1) begin : decode
    // Each binary bit is the parity of the Gray prefix down to that bit.
    assign binary_out[bit_index] = ^gray_in[WIDTH-1:bit_index];
  end
endmodule
```

gray_out直接按反射Gray定义编码；binary_out每位是gray_in高位前缀的归约异或。generate的bit_index在展开时为常量，所以切片可综合。模块没有寄存器，不能用它替代异步FIFO中的注册Gray发布和同步链。

```systemverilog
module axil_regs2 (
  input logic aclk, aresetn,
  input logic [7:0] awaddr,
  input logic [2:0] awprot,
  input logic awvalid,
  output logic awready,
  input logic [31:0] wdata,
  input logic [3:0] wstrb,
  input logic wvalid,
  output logic wready,
  output logic [1:0] bresp,
  output logic bvalid,
  input logic bready,
  input logic [7:0] araddr,
  input logic [2:0] arprot,
  input logic arvalid,
  output logic arready,
  output logic [31:0] rdata,
  output logic [1:0] rresp,
  output logic rvalid,
  input logic rready
);
  logic [31:0] reg0, reg1;
  logic aw_pending, w_pending;
  logic [7:0] saved_addr;
  logic [31:0] saved_data;
  logic [3:0] saved_strb;
  integer lane;
  // READY depends only on registered state, never on a bus input.
  assign awready = !aw_pending && !bvalid;
  assign wready = !w_pending && !bvalid;
  assign arready = !rvalid;

  always_ff @(posedge aclk or negedge aresetn) begin
    if (!aresetn) begin
      reg0 <= '0;
      reg1 <= '0;
      aw_pending <= 1'b0;
      w_pending <= 1'b0;
      saved_addr <= '0;
      saved_data <= '0;
      saved_strb <= '0;
      bvalid <= 1'b0;
      bresp <= 2'b00;
      rvalid <= 1'b0;
      rdata <= '0;
      rresp <= 2'b00;
    end else begin
      if (bvalid && bready) bvalid <= 1'b0;
      if (rvalid && rready) rvalid <= 1'b0;
      // AW and W may arrive in either order. Save each exactly once.
      if (awvalid && awready) begin
        saved_addr <= awaddr;
        aw_pending <= 1'b1;
      end
      if (wvalid && wready) begin
        saved_data <= wdata;
        saved_strb <= wstrb;
        w_pending <= 1'b1;
      end
      // Commit one edge after the second input handshake; no bypass.
      if (aw_pending && w_pending && !bvalid) begin
        aw_pending <= 1'b0;
        w_pending <= 1'b0;
        bvalid <= 1'b1;
        bresp <= 2'b10;
        if (saved_addr == 8'h00 || saved_addr == 8'h04) begin
          bresp <= 2'b00;
          for (lane = 0; lane < 4; lane = lane + 1) begin
            if (saved_strb[lane]) begin
              if (saved_addr == 8'h00)
                reg0[8*lane +: 8] <= saved_data[8*lane +: 8];
              else
                reg1[8*lane +: 8] <= saved_data[8*lane +: 8];
            end
          end
        end
      end
      // Snapshot at AR acceptance. Same-edge writes update after this read.
      if (arvalid && arready) begin
        rvalid <= 1'b1;
        rresp <= 2'b00;
        case (araddr)
          8'h00: rdata <= reg0;
          8'h04: rdata <= reg1;
          default: begin
            rdata <= '0;
            rresp <= 2'b10;
          end
        endcase
      end
    end
  end
  // AxPROT is accepted but intentionally ignored in this unprivileged model.
endmodule
```

aw_pending与w_pending代表两个独立槽位。只有旧状态两个槽都满且没有B响应才提交，所以第二次握手后不会当沿立刻提交；这是有意规定的吞吐契约。B/R在等待时没有覆盖赋值，payload持续保持。读块与写块共用一个时序进程，但寄存器NBA仍保证同沿读旧值；协议没有替我们定义所有设备的读写冲突语义。精确8bit地址比较避免把0x08或未对齐地址别名到有效寄存器。
